function overflowReport() {
  const card = document.getElementById('card');
  const cr = card.getBoundingClientRect();
  const bad = [];
  card.querySelectorAll('*').forEach(el => {
    if (!el.getClientRects().length) return;
    const b = el.getBoundingClientRect();
    if (getComputedStyle(el).position === 'absolute') return;
    if (b.left < cr.left - 0.5 || b.right > cr.right + 0.5 ||
        b.top < cr.top - 0.5 || b.bottom > cr.bottom + 0.5) {
      bad.push([el.className || el.tagName, Math.round(b.left), Math.round(b.top), Math.round(b.right), Math.round(b.bottom)]);
    }
    if (el.scrollWidth > el.clientWidth + 1 && getComputedStyle(el).overflow !== 'hidden' && el.children.length === 0) {
      bad.push(['scrollW:' + (el.className || el.tagName), el.scrollWidth, el.clientWidth]);
    }
  });
  return bad;
}

function fit() {
  const inner = document.querySelector('.inner');
  const h1 = document.querySelector('h1');
  h1.style.fontSize = '';
  let fs = parseFloat(getComputedStyle(h1).fontSize);
  const overflow = () => inner.scrollHeight > inner.clientHeight + 0.5 ||
                         inner.scrollWidth  > inner.clientWidth + 0.5 ||
                         overflowReport().length > 0;
  let guard = 0;
  while (overflow() && fs > 18 && guard++ < 400) {
    fs -= 1;
    h1.style.fontSize = fs + 'px';
  }
  return { fs, bad: overflowReport() };
}
window.overflowReport = overflowReport;

